Node* closest = nullptr;
float min_dist_sq = std::numeric_limits<float>::max();

for (const auto& kv : graph.nodes) {
    Node* node = kv.second;
    if (node->on_footway) continue;

    float dx = node->x - x;
    float dy = node->y - y;
    float dist_sq = dx * dx + dy * dy;

    if (dist_sq < min_dist_sq) {
        min_dist_sq = dist_sq;
        closest = node;
    }
}

return closest;
